export function getVisitas(locale: Locale): VisitaHistorica[] {
  let visitas_lang: VisitaTranslation[] = []

  switch (locale) {
    case 'en':
      visitas_lang = VISITAS_EN
      break
    case 'it':
      visitas_lang = VISITAS_IT
      break
    case 'fr':
      visitas_lang = VISITAS_FR
      break
    case 'de':
      visitas_lang = VISITAS_DE
      break
    case 'pt':
      visitas_lang = VISITAS_PT
      break
    case 'ca':
      visitas_lang = VISITAS_CA
      break
    case 'gl':
      visitas_lang = VISITAS_GL
      break
    case 'eu':
      visitas_lang = VISITAS_EU
      break
    default:
      return visitas
  }

  return visitas.map((v, i) => {
    const tr = visitas_lang[i]
    if (!tr) return v
    return {
      ...v,
      papaNombre: tr.papaNombre,
      nombre: tr.nombre,
      contextoHistorico: tr.contextoHistorico,
      datoRelevante: tr.datoRelevante,
      actos: tr.actos ?? v.actos,
      ciudades: tr.ciudades ?? v.ciudades,
    }
  })
}

